import json
import sys

from .core import balances, settle
from .errors import ValidationError
from .money import format_money


def reject_json_constant(value):
    raise ValueError(f"invalid JSON constant {value!r}")


def json_number(_value):
    # The group schema uses strings for every numeric field.
    return None


def main(argv=None):
    argv = sys.argv[1:] if argv is None else argv
    if len(argv) != 2:
        print("usage: python3 -m ledger {balances,settle} GROUP.json", file=sys.stderr)
        return 1
    command, path = argv
    if command not in ("balances", "settle"):
        print(f"unknown command {command!r}", file=sys.stderr)
        return 1
    try:
        with open(path, encoding="utf-8-sig") as f:
            group = json.load(
                f, parse_int=json_number, parse_float=json_number,
                parse_constant=reject_json_constant,
            )
    except (OSError, ValueError, RecursionError) as error:
        print(f"error: {error}", file=sys.stderr)
        return 1

    try:
        if command == "balances":
            for name, cents in sorted(balances(group).items()):
                print(f"{name}: {format_money(cents, signed=True)}")
        else:
            transfers = settle(group)
            if not transfers:
                print("all settled")
            for frm, to, cents in transfers:
                print(f"{frm} -> {to}: {format_money(cents)}")
    except ValidationError as error:
        print(f"error: {error}", file=sys.stderr)
        return 2
    return 0
from __future__ import annotations

from heapq import heapify, heappop, heappush

from .model import load_group


def balances(group: dict) -> dict[str, int]:
    members, expenses = load_group(group)
    result = dict.fromkeys(members, 0)
    for payer, amount, shares in expenses:
        result[payer] += amount
        for name, owed in shares.items():
            result[name] -= owed
    return result


def settle(group: dict) -> list[tuple[str, str, int]]:
    net = balances(group)
    # Negative amounts put the largest debt and credit first, with names breaking ties.
    debtors = [(amount, name) for name, amount in net.items() if amount < 0]
    creditors = [(-amount, name) for name, amount in net.items() if amount > 0]
    heapify(debtors)
    heapify(creditors)

    transfers = []
    while debtors:
        debt, debtor = heappop(debtors)
        credit, creditor = heappop(creditors)
        paid = min(-debt, -credit)
        transfers.append((debtor, creditor, paid))
        if debt + paid < 0:
            heappush(debtors, (debt + paid, debtor))
        if credit + paid < 0:
            heappush(creditors, (credit + paid, creditor))
    return transfers
import re

from .errors import ValidationError
from .money import parse_hundredths
from .splits import split_equal, split_exact, split_percent


_INVALID_NAME_CHARACTERS = re.compile(r"[\n\r\v\f\x1c-\x1e\x85\u2028\u2029\ud800-\udfff]")


def normalize_name(value):
    if not isinstance(value, str):
        raise ValidationError("names must be strings")
    name = value.strip().lower()
    if not name:
        raise ValidationError("names must be non-empty strings")
    if _INVALID_NAME_CHARACTERS.search(name):
        raise ValidationError("names must be valid Unicode on a single line")
    return name


def member_name(value, members_by_key, role):
    name = normalize_name(value)
    member = members_by_key.get(name.casefold())
    if member is None:
        raise ValidationError(f"unknown {role} {name!r}")
    return member


def participant_amounts(split, field, members_by_key):
    values = split.get(field)
    if not isinstance(values, dict):
        raise ValidationError(f"{field} must be an object")
    normalized = {}
    for raw_name, value in values.items():
        name = member_name(raw_name, members_by_key, "participant")
        if name in normalized:
            raise ValidationError(f"duplicate participant {name!r}")
        normalized[name] = value
    return normalized


def expense_shares(amount, split, members_by_key):
    if not isinstance(split, dict):
        raise ValidationError("split must be an object")
    kind = split.get("type")
    if not isinstance(kind, str):
        raise ValidationError("split type must be a string")
    if kind == "equal":
        if "among" not in split:
            return split_equal(amount, members_by_key.values())
        among = split["among"]
        if not isinstance(among, list) or not among:
            raise ValidationError("among must be a non-empty list")
        participants = [member_name(name, members_by_key, "participant") for name in among]
        if len(set(participants)) != len(participants):
            raise ValidationError("among contains a duplicate participant")
        return split_equal(amount, participants)
    if kind == "exact":
        return split_exact(amount, participant_amounts(split, "amounts", members_by_key))
    if kind == "percent":
        return split_percent(amount, participant_amounts(split, "percents", members_by_key))
    raise ValidationError(f"unknown split type {kind!r}")


def load_group(data):
    """Validate a group and return normalized members and expenses with shares."""
    if not isinstance(data, dict):
        raise ValidationError("group must be an object")
    currency = data.get("currency")
    if not isinstance(currency, str) or not re.fullmatch(r"[A-Za-z]{3}", currency):
        raise ValidationError("currency must be a three-letter code")
    raw_members = data.get("members")
    if not isinstance(raw_members, list) or not raw_members:
        raise ValidationError("members must be a non-empty list")
    members = [normalize_name(name) for name in raw_members]
    members_by_key = {name.casefold(): name for name in members}
    if len(members_by_key) != len(members):
        raise ValidationError("members contains a duplicate name")
    raw_expenses = data.get("expenses")
    if not isinstance(raw_expenses, list):
        raise ValidationError("expenses must be a list")

    expenses = []
    expense_ids = set()
    for index, exp in enumerate(raw_expenses, start=1):
        if not isinstance(exp, dict):
            raise ValidationError(f"expense #{index} must be an object")
        expense_id = exp.get("id")
        if not isinstance(expense_id, str):
            raise ValidationError(f"expense #{index} must have a string id")
        if expense_id in expense_ids:
            raise ValidationError(f"expense {expense_id}: duplicate id")
        expense_ids.add(expense_id)

        try:
            payer = member_name(exp.get("payer"), members_by_key, "payer")
            amount = parse_hundredths(exp.get("amount"), "expense amount")
            if amount <= 0:
                raise ValidationError("expense amount must be greater than zero")
            shares = expense_shares(amount, exp.get("split"), members_by_key)
        except ValidationError as error:
            raise ValidationError(f"expense {expense_id}: {error}") from error
        expenses.append((payer, amount, shares))
    return members, expenses
import re
from decimal import Decimal

from .errors import ValidationError


_DECIMAL_STRING = re.compile(r"([0-9]+)(?:\.([0-9]{1,2}))?")


def parse_hundredths(value, label):
    """Parse cents or hundredths of a percent from a decimal string."""
    match = _DECIMAL_STRING.fullmatch(value) if isinstance(value, str) else None
    if match is None:
        raise ValidationError(f"{label} must be a decimal string with at most two places")
    whole, fraction = match.groups(default="")
    # Decimal converts whole numbers without Python's int/string digit limit.
    return int(Decimal(whole)) * 100 + int(fraction.ljust(2, "0"))


def format_money(cents, *, signed=False):
    sign = ""
    if cents < 0:
        sign = "-"
    elif cents > 0 and signed:
        sign = "+"
    whole, fraction = divmod(abs(cents), 100)
    return f"{sign}{Decimal(whole):f}.{fraction:02d}"
from .errors import ValidationError
from .money import parse_hundredths


def split_equal(amount, among):
    share, leftover = divmod(amount, len(among))
    shares = {name: share for name in among}
    if leftover:
        for name in sorted(among)[:leftover]:
            shares[name] += 1
    return shares


def split_exact(amount, amounts):
    shares = {name: parse_hundredths(value, "exact share") for name, value in amounts.items()}
    if sum(shares.values()) != amount:
        raise ValidationError("exact shares must add up to the expense amount")
    return shares


def split_percent(amount, percents):
    percentages = {
        name: parse_hundredths(value, "percentage") for name, value in percents.items()
    }
    if any(value <= 0 for value in percentages.values()):
        raise ValidationError("percentages must be greater than zero")
    if sum(percentages.values()) != 10_000:
        raise ValidationError("percentages must add up to 100")

    shares = {}
    remainders = []
    for name, percentage in percentages.items():
        shares[name], remainder = divmod(amount * percentage, 10_000)
        remainders.append((-remainder, name))
    leftover = amount - sum(shares.values())
    if leftover:
        for _, name in sorted(remainders)[:leftover]:
            shares[name] += 1
    return shares

